  [/\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, '[REDACTED:jwt]'],
  [/\b(Bearer|Basic|Token)\s+[A-Za-z0-9._~+\/=-]{8,}/g, '$1 [REDACTED:token]'],
  [/\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/g, '[REDACTED:github_token]'],
  [/\bxox[abposr]-[A-Za-z0-9-]{10,}/g, '[REDACTED:slack_token]'],
  [/https:\/\/hooks\.slack\.com\/services\/[A-Za-z0-9\/]+/g, '[REDACTED:slack_webhook]'],
  [/\bsk-(?:proj-|ant-(?:api\d+-)?)?[A-Za-z0-9_-]{20,}/g, '[REDACTED:api_key]'],
  [/\b((?:[a-z0-9]+[_-])*(?:password|passwd|pwd|pass|secret|token|api[_-]?key|apikey|access[_-]?key|private[_-]?key|client[_-]?secret|credentials?|cookie)["'\\]*\s*[:=]\s*["'\\]*)([^\s"'\\&,;}\]]{3,})/gi, '$1[REDACTED]'],
