      const o = JSON.parse(c);
      if (o && typeof o === 'object' && !Array.isArray(o)) return o;
    } catch (e) { /* try the next candidate */ }
  }
  return null;
}

let ai;
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* left as text */ } }
if (!status || status >= 300) {
  ai = { ok: false, note: `AI summary unavailable (LLM HTTP ${status || 'no response'}). Raw alert data below.` };
} else {
  const answer = parseJsonAnswer(extractText(body));
  if (!answer || !answer.summary) {
    ai = { ok: false, note: 'AI summary unavailable (the model did not return the expected JSON). Raw alert data below.' };
  } else {
    ai = {
      ok: true, model,
      summary: String(answer.summary),
      likely_cause: answer.likely_cause ? String(answer.likely_cause) : '',
      first_checks: Array.isArray(answer.first_checks) ? answer.first_checks.map(String) : [],
      severity_assessment: answer.severity_assessment || '',
    };
  }
}

return [{ json: { url: (S.notify || {}).url, ai_ok: ai.ok, body: ftwRenderMessage(prep.group, ai, S) } }];

// ---- redaction (runs before anything leaves n8n for the LLM or the chat webhook) ----
const REDACTION_RULES = [
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(?:-----END [A-Z ]*PRIVATE KEY-----|$)/g, '[REDACTED:private_key]'],
  [/\b([a-z][a-z0-9+.-]*:\/\/)[^\s:@\/"'<>]+:[^\s@\/"'<>]+@/gi, '$1[REDACTED:credentials]@'],
  [/\b(?:AKIA|ASIA|AGPA|AIDA|AROA|ANPA)[0-9A-Z]{16}\b/g, '[REDACTED:aws_access_key]'],
  [/\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, '[REDACTED:jwt]'],
  [/\b(Bearer|Basic|Token)\s+[A-Za-z0-9._~+\/=-]{8,}/g, '$1 [REDACTED:token]'],
  [/\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/g, '[REDACTED:github_token]'],
  [/\bxox[abposr]-[A-Za-z0-9-]{10,}/g, '[REDACTED:slack_token]'],
  [/https:\/\/hooks\.slack\.com\/services\/[A-Za-z0-9\/]+/g, '[REDACTED:slack_webhook]'],
  [/\bsk-(?:proj-|ant-(?:api\d+-)?)?[A-Za-z0-9_-]{20,}/g, '[REDACTED:api_key]'],
  [/\b((?:[a-z0-9]+[_-])*(?:password|passwd|pwd|pass|secret|token|api[_-]?key|apikey|access[_-]?key|private[_-]?key|client[_-]?secret|credentials?|cookie)["'\\]*\s*[:=]\s*["'\\]*)([^\s"'\\&,;}\]]{3,})/gi, '$1[REDACTED]'],
];
const EMAIL_RULE = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
const IPV4_RULE = /\b(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}\b/g;

function ftwRedactText(text, cfg) {
  cfg = cfg || {};
  let out = text == null ? '' : String(text);
  let count = 0;
  const apply = (rx, repl) => {
    out = out.replace(rx, (...m) => { count++; return repl.replace(/\$(\d)/g, (_, i) => m[Number(i)] || ''); });
  };
  for (const [rx, repl] of REDACTION_RULES) apply(rx, repl);
  if (cfg.emails !== false) apply(EMAIL_RULE, '[REDACTED:email]');
  if (cfg.ipv4 === true) apply(IPV4_RULE, '[REDACTED:ip]');
  return { text: out, count };
}

// Replace whole values whose KEY looks sensitive (a label named password, token, ...).
function ftwRedactKeys(value, cfg) {
  cfg = cfg || {};
  let rx;
  try { rx = new RegExp(cfg.drop_keys_pattern || '(pass(word|wd)?|secret|token|authorization|cookie|api[_-]?key|credential|private[_-]?key)', 'i'); }
  catch (e) { rx = /(password|secret|token|authorization|cookie|api[_-]?key|credential)/i; }
  const walk = (v) => {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === 'object') {
      const o = {};
      for (const [k, x] of Object.entries(v)) o[k] = (rx.test(k) && (typeof x === 'string' || typeof x === 'number')) ? '[REDACTED]' : walk(x);
      return o;
    }
    return v;
  };
  return walk(value);
}

// ---- alert helpers ----
const SEV_MAP = { critical: 'critical', page: 'critical', p1: 'critical', sev1: 'critical', error: 'critical', high: 'critical',
  warning: 'warning', warn: 'warning', p2: 'warning', sev2: 'warning', medium: 'warning',
  info: 'info', informational: 'info', low: 'info', none: 'info', p3: 'info', p4: 'info' };
const SEV_RANK = { critical: 3, warning: 2, info: 1 };
const SEV_ICON = { critical: ':rotating_light:', warning: ':warning:', info: ':information_source:' };

function ftwSev(labels) {
  const s = String((labels || {}).severity || (labels || {}).priority || 'warning').toLowerCase();
  return SEV_MAP[s] || 'warning';
}
function ftwTrunc(s, n) {
  s = s == null ? '' : String(s);
  return s.length > n ? s.slice(0, Math.max(0, n - 1)) + '…' : s;
}
function ftwWhere(labels) {
  const keys = ['cluster', 'namespace', 'service', 'job', 'instance', 'pod', 'container', 'deployment', 'node'];
  return keys.filter(k => labels && labels[k] && labels[k] !== '[REDACTED]').map(k => `${k}=${labels[k]}`).join(' ');
}
function ftwFingerprint(labels) {
  const txt = Object.keys(labels || {}).sort().map(k => k + '=' + labels[k]).join(',');
  let h = 0x811c9dc5;
  for (let i = 0; i < txt.length; i++) h = Math.imul(h ^ txt.charCodeAt(i), 16777619) >>> 0;
  return ('00000000' + h.toString(16)).slice(-8);
}
function ftwSilenceUrl(base, labels) {
  if (!base) return '';
  const matchers = Object.keys(labels || {}).filter(k => k !== 'severity' && labels[k] !== '[REDACTED]').sort()
    .map(k => `${k}="${String(labels[k]).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`).join(',');
  return `${String(base).replace(/\/+$/, '')}/#/silences/new?filter=${encodeURIComponent('{' + matchers + '}')}`;
}

// One Alertmanager webhook v4 payload -> one normalised group.
function ftwNormalizeGroup(body, S) {
  if (!body || !Array.isArray(body.alerts)) {
    throw new Error('Not an Alertmanager webhook payload: alerts[] is missing. Check the receiver URL in alertmanager.yml.');
  }
  const red = (S.llm || {}).redact || {};
  const alerts = body.alerts.map(a => {
    const labels = ftwRedactKeys(a.labels || {}, red);
    const annotations = ftwRedactKeys(a.annotations || {}, red);
    return {
      status: a.status === 'resolved' ? 'resolved' : 'firing',
      alertname: labels.alertname || 'UnnamedAlert',
      severity: ftwSev(labels),
      labels, annotations,
      summary: annotations.summary || annotations.message || annotations.description || '',
      where: ftwWhere(labels),
      starts_at: a.startsAt || '',
      generator_url: a.generatorURL || '',
      runbook_url: annotations.runbook_url || annotations.runbook || '',
      fingerprint: a.fingerprint || ftwFingerprint(labels),
      silence_url: ftwSilenceUrl(((S.links || {}).alertmanager_url) || body.externalURL, labels),
    };
  });
  const firing = alerts.filter(a => a.status === 'firing');
  const resolved = alerts.filter(a => a.status === 'resolved');
  const names = [...new Set(alerts.map(a => a.alertname))];
  const common = ftwRedactKeys(body.commonLabels || {}, red);
  return {
    status: firing.length ? 'firing' : 'resolved',
    severity: firing.length ? firing.map(a => a.severity).sort((x, y) => SEV_RANK[y] - SEV_RANK[x])[0] : (alerts[0] ? alerts[0].severity : 'info'),
    receiver: body.receiver || '',
    group_key: body.groupKey || '',
    group_labels: body.groupLabels || {},
    common_labels: common,
    external_url: body.externalURL || '',
    truncated_alerts: body.truncatedAlerts || 0,
    alerts, firing, resolved, names,
    where: ftwWhere(common),
  };
}

function ftwTitle(g) {
  const list = g.status === 'firing' ? g.firing : g.resolved;
  const names = g.names.slice(0, 3).join(', ') + (g.names.length > 3 ? ` +${g.names.length - 3}` : '');
  return ftwTrunc(`[${g.status.toUpperCase()}:${list.length}] ${names}${g.where ? ' (' + g.where + ')' : ''}`, 140);
}

// Render the chat message. `ai` is null (resolved), {ok:true,...} or {ok:false, note}.
function ftwRenderMessage(g, ai, S) {
  const list = g.status === 'firing' ? g.firing : g.resolved;
  const lines = [`${SEV_ICON[g.severity] || ''} *${ftwTitle(g)}*`];
  if (ai && ai.ok) {
    lines.push('', ftwTrunc(ai.summary, 600));
    if (ai.likely_cause) lines.push('', `*Likely cause:* ${ftwTrunc(ai.likely_cause, 400)}`);
    const checks = (ai.first_checks || []).slice(0, 5).map(c => `• ${ftwTrunc(c, 200)}`);
    if (checks.length) lines.push('', '*First checks:*', ...checks);
  } else if (ai && !ai.ok) {
    lines.push('', `_${ai.note}_`);
  }
  lines.push('', '*Alerts:*');
  for (const a of list.slice(0, 10)) {
    lines.push(`• [${a.severity}] ${a.alertname}${a.where ? ` — ${a.where}` : ''}${a.summary ? `: ${ftwTrunc(a.summary, 200)}` : ''}`);
  }
  if (list.length > 10) lines.push(`• …and ${list.length - 10} more`);
  const first = list[0] || {};
  const links = [];
  if (first.runbook_url && /^https?:\/\//i.test(first.runbook_url)) links.push(`<${first.runbook_url}|Runbook>`);
  if (first.generator_url) links.push(`<${first.generator_url}|Source>`);
  if (g.status === 'firing' && first.silence_url) links.push(`<${first.silence_url}|Silence>`);
  if (links.length) lines.push('', links.join(' · '));
  if (ai && ai.ok) lines.push('', `_AI-generated with ${ftwTrunc(ai.model, 60)} — verify before acting._`);
  const text = ftwRedactText(lines.join('\n'), (S.llm || {}).redact).text;
  const format = String((S.notify || {}).format || 'slack').toLowerCase();
  if (format === 'generic') {
    return { title: ftwTitle(g), status: g.status, severity: g.severity, text,
      alerts: list.slice(0, 10).map(a => ({ alertname: a.alertname, severity: a.severity, where: a.where, summary: a.summary, fingerprint: a.fingerprint })),
      ai: ai && ai.ok ? { summary: ai.summary, likely_cause: ai.likely_cause, first_checks: ai.first_checks, model: ai.model } : null };
  }
  return { text };
}

// Resolved groups: one short message, no LLM call.
const prep = $('Prepare alert group').first().json;
const S = prep.settings;
return [{ json: { url: (S.notify || {}).url, ai_ok: false, body: ftwRenderMessage(prep.group, null, S) } }];
